ptrdiff_t find_int(const int *a, size_t n, int target) {
    for (size_t i = 0; i < n; ++i) {
        if (a[i] == target) return (ptrdiff_t)i;
    }
    return -1;
}

static int compare_int(const void *lhs, const void *rhs) {
    int a = *(const int *)lhs;
    int b = *(const int *)rhs;
    return (a > b) - (a < b);
}
